static void zdt_move_frame(unsigned char out[13], int addr, int dir,
                           int rpm, int acc, uint32_t pulses, int raf, int snf)
{
    out[0]  = (unsigned char)addr;
    out[1]  = 0xFD;
    out[2]  = (unsigned char)(dir ? 1 : 0);
    out[3]  = (unsigned char)((rpm >> 8) & 0xFF);
    out[4]  = (unsigned char)(rpm & 0xFF);
    out[5]  = (unsigned char)(acc & 0xFF);
    out[6]  = (unsigned char)((pulses >> 24) & 0xFF);
    out[7]  = (unsigned char)((pulses >> 16) & 0xFF);
    out[8]  = (unsigned char)((pulses >> 8)  & 0xFF);
    out[9]  = (unsigned char)(pulses & 0xFF);
    out[10] = (unsigned char)(raf ? 1 : 0);
    out[11] = (unsigned char)(snf ? 1 : 0);
    out[12] = 0x6B;
}

