static int  g_use_pl = 0;
static int  g_skip_en = 0;   /* -J: 跳过使能阶段 */
static long g_pl_pos[5];          /* signed pulses per axis, 1..4 */

static int pl_send(void)
{
    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) { perror("/dev/mem"); return -1; }
    volatile unsigned int *r = (volatile unsigned int *)mmap(
        NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0x40000000UL);
    if (r == MAP_FAILED) { perror("mmap"); close(fd); return -1; }

    r[0] = 0x8;                        /* uart_sel=1, no start */
    r[7] = 1;                          /* clear done */
    usleep(2000);

    r[2] = (unsigned int)g_pl_pos[1];
    r[3] = (unsigned int)g_pl_pos[2];
    r[4] = (unsigned int)g_pl_pos[3];
    r[5] = (unsigned int)g_pl_pos[4];

    r[0] = 0x8u | (g_skip_en ? 0x10u : 0u) | (g_abs ? 0x2u : 0u) | 0x1u;   /* 同步已取消 */

    int ok = 0;
    for (int i = 0; i < 3000; i++) {          /* up to 3 s */
        if (r[6] & 0x2) { ok = 1; break; }
        usleep(1000);
    }
    r[0] = 0x8;                        /* keep sel, no start */
    if (!ok) fprintf(stderr, "pl: timeout waiting done\n");
    munmap((void *)r, 4096);
    close(fd);
    return ok ? 0 : -1;
}
