static void save_pos(void)
{
    FILE *f = fopen("/tmp/ik_pos", "w");
    if (!f) return;
    fprintf(f, "%ld %ld %ld %ld`n", g_cur[1], g_cur[2], g_cur[3], g_cur[4]);
    fclose(f);
}

static void load_pos(void)
{
    FILE *f = fopen("/tmp/ik_pos", "r");
    if (!f) return;
    if (fscanf(f, "%ld %ld %ld %ld", &g_cur[1], &g_cur[2], &g_cur[3], &g_cur[4]) != 4) {
        g_cur[1] = g_cur[2] = g_cur[3] = g_cur[4] = 0;
    }
    fclose(f);
}

static void load_cfg(const char *path)
{
    FILE *f = fopen(path, "r");
    char line[128], key[32];
    double v;
    if (!f) return;
    while (fgets(line, sizeof line, f)) {
        if (line[0] == '#' || line[0] == 10 || line[0] == 13) continue;
        if (sscanf(line, "%31[^= \t]=%lf", key, &v) != 2) continue;
        if      (!strcmp(key, "LINK1"))  g_link1  = v;
        else if (!strcmp(key, "LINK2"))  g_link2  = v;
        else if (!strcmp(key, "BASE_H")) g_base_h = v;
        else if (!strcmp(key, "TOOL_X")) g_tool_x = v;
        else if (!strcmp(key, "TOOL_Z")) g_tool_z = v;
        else if (!strcmp(key, "J2Z"))    g_j2z    = (int)v;
        else if (!strcmp(key, "J3Z"))    g_j3z    = (int)v;
        else if (!strcmp(key, "J4Z"))    g_j4z    = (int)v;
        else if (!strcmp(key, "ELBOW"))  g_elbow  = (int)v;
        else if (!strcmp(key, "SWAP"))   g_swap   = (int)v;
        else if (!strcmp(key, "ABS"))    g_abs    = (int)v;
        else if (!strcmp(key, "J1O"))    g_j1off  = (int)v;
        else if (!strcmp(key, "P1"))     pulses_per_rev[1] = (int)v;
        else if (!strcmp(key, "P2"))     pulses_per_rev[2] = (int)v;
        else if (!strcmp(key, "P3"))     pulses_per_rev[3] = (int)v;
        else if (!strcmp(key, "P4"))     pulses_per_rev[4] = (int)v;
    }
    fclose(f);
}


