{
    const char *dev = "/dev/ttyUL1";
    int baud = 115200;
    int addr[5] = {0, 1, 2, 3, 4};
    int rpm = 300;
    int dry = 0;                 /* -n: 闂傚倸鍊搁崐鎼佸磹閹间礁纾归柟闂寸绾惧綊鏌熼梻瀵割槮缁惧墽鎳撻—鍐偓锝庝簼閹癸綁鏌ｉ鐐搭棞闁靛棙甯掗～婵嬫晲閸涱剙顥氬┑掳鍊楁慨鐑藉磻濞戔懞鍥偨缁嬫寧鐎梺鐟板⒔缁垶宕戦幇鐗堢厱闁归偊鍨扮槐锕傛煟閵忋垻甯涘ǎ鍥э躬閹瑩顢旈崟銊ヤ壕闁哄稁鍘介崑瀣繆閵堝懎鏆熼柣顓熺懇閺岀喖鎮欓鍌涜弴闂侀€炲苯澧柟铏锝嗙節濮橆儵銊╂煥閺冣偓閸庡啿顕ｉ搹顐ょ瘈闁汇垽娼ч埢鍫熺箾娴ｅ啿鍚樺☉銏╂晣闁绘劕绉堕崰鏍х暦婵傜唯闁挎梹鍎抽獮鎰攽閻愯埖褰х紒韫矙楠炲鏁撻悩鑼崶濠殿喗銇涢崑鎾绘煛瀹€瀣？濞寸媴绠撳畷婊嗩槷婵℃彃鐗撳铏光偓鍦濞兼劙鏌涢妸銉т虎闁伙絿鍏橀幃銏㈠枈鏉堛劍娅囬梻渚€娼х换鎺撴叏瀹€鍕婵犻潧鍟弬鈧梻浣虹帛閸旀牕顭囧▎鎾村€堕柨鏇炲€归悡娆戠磼鐎ｎ偄顕滈柟鎻掓憸缁辨帡顢欓懞銉閻庤娲栫紞濠囥€侀弴銏犖ч柛灞剧⊕閺嗐倖绻濋悽闈浶ラ柡浣告啞閹便劑寮堕幊銊︽そ婵″爼宕ㄩ鎯у毐闂傚倸鍊搁崐椋庣矆娓氣偓楠炲鏁嶉崟顐㈢亰闂佸壊鍋侀崹濠氭儗閸℃ぜ鈧帒顫濋敐鍛闁诲氦顫夊ú妯煎垝瀹€鍕仼闁绘垼妫勯悙濠囨煃閸濆嫬鏋︾紒鍗炲暱閳规垿鎮欓懜闈涙锭缂備礁寮跺畷姗€濡甸幇鏉跨闁冲搫鍠氬ú鎼佹⒑缂佹ê濮﹂柛鎾寸〒瀵囧焵椤掑嫭鈷戦梻鍫熺洴閻涙粎绱掗幓鎺戔挃婵炴垵鐏氶妶锝夊礃閳轰焦鐤勯梺璇茬箳閸嬫稖銇愰悙鍨床闁糕剝绋掗悡娆戠磽娴ｅ顏嗙箔瑜嶉…鑳檪缂佺姵鎹囧濠氬灳瀹曞洦娈曢梺閫炲苯澧寸€规洑鍗冲浠嬵敇閻樿尙銈﹂梻浣虹《閸撴繈宕欓悷鎷旓絾銈ｉ崘鈹炬嫼闂佸湱顭堝ù鐑藉煡婢跺瞼纾煎璺猴功閸╋綁鏌涢埞鎯т壕婵＄偑鍊栫敮濠囨嚄閸洖鐓€闁哄洨濮风壕濂告偣閸ャ劌绲绘い蹇ｅ亝娣囧﹪宕ｆ径濠傤潚濡ょ姷鍋為…鍥焵椤掍胶鈯曢柨姘亜鎼淬垺灏扮紒缁樼〒閳ь剛鏁搁…鍫濈摥婵＄偑鍊栭崹鐢稿箠濮椻偓閻涱喖螖閸涱喖浠洪梺鍛婄☉鑹岄柟閿嬫そ濮婅櫣娑甸崨顓濇睏闂佺顑嗙粙鎺撶┍婵犲洦鍋傞幖鎼枤閸炵敻鎮峰鍐㈤棁澶愭煟閹达絾顥夌紒鈧崱娑欑厵闁绘垶锚閻忓秹鏌＄€ｎ亪鍙勯柡宀€鍠栭弻鍥晝閳ь剚鏅堕幍顔剧＜闁归偊鍠栨禒杈ㄦ叏婵犲洨绱伴柕鍥ㄥ姍楠炴帡骞嬪鍐╃€抽梻鍌欑閹诧繝骞愭繝姘剮妞ゆ牜鍋戦埀顑跨閳诲氦绠涢弴鐔哥暦闂備礁鎲″ú锕傚礂濮椻偓楠炲繐煤椤忓應鎷洪梻鍌氱墐閺呮盯鎯佸鍫熺厱婵☆垱浜介崑銏⑩偓瑙勬礃缁诲嫰鍩€椤掑﹦绉甸柛鐘愁殜閹繝寮撮姀锛勫帾婵犵數鍋涢悘婵嬪礉濠婂牊鍋ｉ柟鏉垮绾捐法绱?*/
    int g_use_mem = 0;
    int i, a = 1;
    load_cfg("/etc/ik.conf");
    load_pos();

    while (a < argc && argv[a][0] == '-') {
        if (!strcmp(argv[a], "-p") && a + 1 < argc) { dev = argv[++a]; a++; }
        else if (!strcmp(argv[a], "-b") && a + 1 < argc) { baud = atoi(argv[++a]); a++; }
        else if (!strcmp(argv[a], "-a") && a + 1 < argc) {
            char *s = argv[++a], *tok;
            int k = 1;
            a++;
            for (tok = strtok(s, ","); tok && k <= 4; tok = strtok(NULL, ","))
                addr[k++] = atoi(tok);
        }
        else if (!strcmp(argv[a], "-r") && a + 1 < argc) { rpm = atoi(argv[++a]); a++; }
        else if (!strcmp(argv[a], "-n")) { dry = 1; a++; }
        else if (!strcmp(argv[a], "-m")) { g_use_mem = 1; a++; }
        else if (!strcmp(argv[a], "-P")) { g_use_pl = 1; g_use_mem = 1; a++; }
        else if (!strcmp(argv[a], "-J")) { g_skip_en = 1; a++; }
        else if (!strcmp(argv[a], "-A") && a + 1 < argc) { g_acc = atoi(argv[++a]); a++; }
        else { fprintf(stderr, "unknown option %s\n", argv[a]); return 2; }
    }
    if (a >= argc) {
        fprintf(stderr,
            "usage:\n"
            "  %s [-p dev] [-b baud] [-a 1,2,3,4] [-r rpm] goto X Y Z\n"
            "  %s [...] angle J1 J2 J3 J4\n"
            "  %s [...] raw AA BB CC ...\n", argv[0], argv[0], argv[0]);
        return 2;
    }

    g_dry = dry;
    if (!dry) {
        if (g_use_mem) {
            if (ul_open() < 0) return 1;
        } else {
            g_fd = serial_open(dev, baud);
            if (g_fd < 0) return 1;
        }
    }

    const char *cmd = argv[a++];

    if (!strcmp(cmd, "raw")) {
        unsigned char buf[256];
        int n = 0;
        for (; a < argc && n < (int)sizeof(buf); a++)
            buf[n++] = (unsigned char)strtoul(argv[a], NULL, 16);
        if (serial_write(buf, n) < 0) return 1;
        printf("sent %d bytes\n", n);
        return 0;
    }

    if (!strcmp(cmd, "angle")) {
        if (a + 4 > argc) { fprintf(stderr, "need 4 angles\n"); return 2; }
        long t[5];
        for (i = 1; i <= 4; i++) t[i] = strtol(argv[a++], NULL, 0);
        if (!g_use_pl)
            for (i = 1; i <= 4; i++) if (enable_axis(addr[i]) < 0) return 1;
        for (i = 1; i <= 4; i++) if (move_joint(i, t[i], addr[i], rpm) < 0) return 1;
        if (g_use_pl) pl_send();
        return 0;
        return 0;
    }

    if (!strcmp(cmd, "enable") || !strcmp(cmd, "disable")) {
        unsigned char f[6];
        int j;
        f[0] = 0;
        f[1] = 0xF3;                 /* 婵犵數濮烽弫鍛婃叏閻戣棄鏋侀柛娑橈攻閸欏繘鏌ｉ幋锝嗩棄闁哄绶氶弻鐔兼⒒鐎靛壊妲紒鐐劤椤兘寮婚敐鍛傜喎鈻庨幆褎顔勭紓鍌欒兌婵挳鎮樺璺何﹂柛鏇ㄥ枤閻も偓闂佸湱鍋撻幆灞轿涢妶鍥╃＝濞达絾褰冩禍鐐節閻㈤潧孝婵炶绠撻幃锟犲礃椤忓懎鏋戝┑鐘诧工閻楀棛绮堥崼銉︾厽闁哄啫鍊哥敮鍫曟煢閸愵亜鏋戠紒缁樼洴楠炲鎮欓崹顐㈡珬闂備胶顭堝ù鐑藉窗閺嶎厼钃熺€广儱顦扮€电姴顭跨捄渚剾婵☆偁鍊濆娲川婵犲懎顥濆銈嗗灥椤︾敻鐛?婵犵數濮烽弫鍛婃叏閻戣棄鏋侀柛娑橈攻閸欏繘鏌ｉ幋锝嗩棄闁哄绶氶弻娑樷槈濮楀牊鏁鹃梺鍛婄懃缁绘劙婀侀梺绋跨箰閸氬绱為幋锔界厱闁靛鍎遍埀顒€婀遍幑銏犫槈濮楀棗鏅犲銈嗘瀹曠敻鎯勬惔锝囩＜闁绘劦鍓欓崝銈嗙箾绾绡€鐎殿喖顭锋俊鍫曞触閵堝懏璐￠柍褜鍓ㄧ紞鍡涘磻閸涘瓨鍋熼柡鍐ㄧ墛閳锋垿鏌熼懖鈺佷粶濠碉紕鏅槐鎺旀嫚閹绘巻鍋撴禒瀣€堕柛鎰靛枟閳锋垿鏌熺粙鎸庢崳缂佺姵鎹囬弻鐔煎礃閺屻儱寮伴悗娈垮枛閸熷潡鍩㈡惔銊ョ闁绘顣槐鏌ユ⒒娓氣偓閳ь剛鍋涢懟顖涙櫠鐎电硶鍋撶憴鍕閻㈩垱甯￠崺銉﹀緞婵炵偓鐎婚棅顐㈡处閹搁妲愰悢灏佹斀闁绘ɑ顔栭弳婊呯磼鏉堛劍绀嬬€规洘鍨块幃鈺伱虹紒妯绘珨闁荤喐绮屽ù椋庡垝鐎ｎ亶鍚嬮柛鈩冨姇娴滄繈姊洪崨濠傚闁哄懏鐩崺鈧い鎺戝€归弳顒勬煙椤旂厧妲婚柍璇叉唉缁犳盯骞欓崘褏妫紓鍌欑婢т粙宕戦幘璇茬畺闁稿瞼鍋涢拑鐔哥箾閹存瑥鐏╃紒顐㈢Ч閺屽秷顧侀柛鎾跺枎閻ｇ柉銇愰幒鎴︽暅濠德板€撶粈浣圭閹烘埈娓婚柕鍫濇椤ュ牓鏌℃笟鍥ф珝鐎规洘鍨块獮妯肩磼濡粯鐝抽梺纭呭亹鐞涖儵宕滃┑瀣€堕柛顐犲灮绾捐棄霉閿濆懏鎯堥弽鈩冪節閻㈤潧浠滈柨鏇ㄤ簻椤曪絾绻濆顓炰簻闂佺绻掗崢褔鍩€椤掑嫭鏁遍柕鍥у楠炴帡宕卞鎯ь棜濠?*/
        f[2] = 0xAB;
        f[3] = (cmd[0] == 'e') ? 1 : 0;
        f[4] = 0x00;
        f[5] = 0x6B;
        for (j = 1; j <= 4; j++) {
            f[0] = (unsigned char)addr[j];
            if (serial_write(f, 6) < 0) return 1;
        }
        printf("%s sent to addr %d,%d,%d,%d\n", cmd, addr[1], addr[2], addr[3], addr[4]);
        return 0;
    }

    if (!strcmp(cmd, "goto")) {
        if (a + 3 > argc) { fprintf(stderr, "need X Y Z (mm)\n"); return 2; }
        double x = atof(argv[a++]), y = atof(argv[a++]), z = atof(argv[a++]);
        ik_out s = ik_solve(x, y, z);
        if (!s.ok) {
            fprintf(stderr, "IK rejected: %s\n", s.why ? s.why : "?");
            return 1;
        }
        printf("target (%.1f, %.1f, %.1f) -> joints deg256: %ld %ld %ld %ld\n",
               x, y, z, s.j1, s.j2, s.j3, s.j4);
        if (!g_use_pl) {
            if (enable_axis(addr[1]) < 0 || enable_axis(addr[2]) < 0 ||
                enable_axis(addr[3]) < 0 || enable_axis(addr[4]) < 0) return 1;
            usleep(200000);   /* wait for driver to finish enabling */
        }
        if (move_joint(1, s.j1, addr[1], rpm) < 0 ||
            move_joint(2, s.j2, addr[2], rpm) < 0 ||
            move_joint(3, s.j3, addr[3], rpm) < 0 ||
            move_joint(4, s.j4, addr[4], rpm) < 0) return 1;
        if (g_use_pl) pl_send();
        /* 4-axis: addr1=base, addr2=shoulder, addr3=elbow, addr4=wrist(keep tool vertical) */
        return 0;
    }

    fprintf(stderr, "unknown command %s\n", cmd);
    return 2;
}
